cases.yaml:
version: 1
defaultAction: deny
rules:
  - session: developer/main
    action: allow
  - agent: [developer, developer-worker]
    node: 'development/*'
    action: allow
  - agent: [developer, developer-worker]
    tool: { source: builtin, name: task }
    args:
      action: [get, update, complete]
      taskId: { task: { owned: true } }
    action: allow
  - agent: { oneOf: [developer, developer-worker] }
    tool: { source: builtin, name: send_to_session }
    args: { sessionId: { session: { relation: parent } } }
    action: allow
  - tool: wait
    action: allow
  - tool: [read, write]
    node: { exact: [master] }
    path: { anyNotWithin: '${workspace}/shared' }
    action: deny
  - node: { current: true }
    action: allow
  - node: { provider: development }
    action: allow
  - tool: { source: [builtin, mcp], server: { exists: false }, name: { equals: status } }
    args: { 'options.mode': { oneOf: [fast, 1, true, null] }, count: 3 }
    action: allow

version: 1
rules:
  - match:
      agent: reviewer
      tool: { source: builtin, name: [send_to_session] }
      args: { sessionId: { session: { sameAgent: true, self: true, relation: [parent, child] } } }
    action: allow
  - action: deny
    tool: {source: builtin, name: create_session}
    args: {agentName: {agent: {sameAgent: false}}}

version: 1
rules:
  - tool: {source: builtin, name: view_session}
    args: {sessionId: {session: {self: false}}}
    action: deny

version: 1
rules:
  - tool: {source: builtin, name: exec}
    args: {sessionId: {session: {self: true}}}
    action: deny
